/*
 * A183125  Magnetic Tower of Hanoi, total number of moves, generated by a
 *          certain algorithm, yielding a "forward moving" non-optimal
 *          solution of the [NEUTRAL ; NEUTRAL ; NEUTRAL] pre-colored puzzle.
 * https://oeis.org/A183125
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 11, u32 n <= 21, u64 n <= 41, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 *  OEIS A183125 – Magnetic Tower of Hanoi, total number of moves
 *
 *  The sequence satisfies, for n ≥ 5:
 *      if n even:  a(n) = 3*a(n-1) - 2*n^2 + 17*n - 43
 *      if n odd : a(n) = 3*a(n-1) - 2*n^2 + 17*n - 42
 *
 *  Initial values:
 *      a(0)=0, a(1)=1, a(2)=4, a(3)=11, a(4)=30
 *
 *  The function below memoises the sequence in a static cache so that
 *  any number of calls in arbitrary order run in O(max_n) time, where
 *  max_n is the largest n requested so far.
 *
 *  All arithmetic is done using seq_t only, which may be an unsigned
 *  integer type of arbitrary width or an arbitrary‑precision class.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Persistent cache and its current maximum index */
    static seq_t *cache = NULL;
    static idx_t max_cached = 0;        /* maximum index for which cache is valid */

    /* Initialise cache with the first five terms if not already done */
    if (cache == NULL) {
        cache = (seq_t *)malloc(5 * sizeof(seq_t));
        if (cache == NULL) return (seq_t)0;   /* allocation failure unlikely */

        cache[0] = (seq_t)0;
        cache[1] = (seq_t)1;
        cache[2] = (seq_t)4;
        cache[3] = (seq_t)11;
        cache[4] = (seq_t)30;

        max_cached = 4;
    }

    /* If the requested value is already cached, return it */
    if (n <= max_cached)
        return cache[n];

    /* Grow the cache to hold index n */
    seq_t *new_cache = (seq_t *)realloc(cache, (n + 1) * sizeof(seq_t));
    if (new_cache == NULL)
        return (seq_t)0;                       /* allocation failure unlikely */
    cache = new_cache;

    /* Compute missing terms from max_cached + 1 up to n */
    for (idx_t i = max_cached + 1; i <= n; ++i) {
        seq_t prev = cache[i - 1];
        seq_t i_seq = (seq_t)i;                 /* cast index to seq_t */
        seq_t quad = i_seq * i_seq;              /* i^2 */

        /* Apply the appropriate recurrence depending on parity of i */
        seq_t term;
        if ((i & 1) == 0) {                    /* i is even */
            term = ((seq_t)3) * prev
                 - ((seq_t)2) * quad
                 + ((seq_t)17) * i_seq
                 - ((seq_t)43);
        } else {                                 /* i is odd */
            term = ((seq_t)3) * prev
                 - ((seq_t)2) * quad
                 + ((seq_t)17) * i_seq
                 - ((seq_t)42);
        }

        cache[i] = term;
    }

    max_cached = n;
    return cache[n];
}
